class Solution:
    def posterReach(self, panels: List[int]) -> List[int]:
        n = len(panels)
        width = [0] * n
        for i in range(n):
            l = i
            while l > 0 and panels[l - 1] >= panels[i]:
                l -= 1
            r = i
            while r < n - 1 and panels[r + 1] >= panels[i]:
                r += 1
            width[i] = r - l + 1
        return width

