class Solution {
    public int[] posterReach(int[] panels) {
        int n = panels.length;
        int[] width = new int[n];
        for (int i = 0; i < n; i++) {
            int l = i;
            while (l > 0 && panels[l - 1] >= panels[i]) l--;
            int r = i;
            while (r < n - 1 && panels[r + 1] >= panels[i]) r++;
            width[i] = r - l + 1;
        }
        return width;
    }
}

