class Solution:
    def posterReach(self, panels: List[int]) -> List[int]:
        n = len(panels)
        left, right = [-1] * n, [n] * n
        stack = []
        for i in range(n):
            while stack and panels[stack[-1]] >= panels[i]:
                stack.pop()
            left[i] = stack[-1] if stack else -1
            stack.append(i)
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and panels[stack[-1]] >= panels[i]:
                stack.pop()
            right[i] = stack[-1] if stack else n
            stack.append(i)
        return [right[i] - left[i] - 1 for i in range(n)]

