class Solution {
    public int[] posterReach(int[] panels) {
        int n = panels.length;
        int[] left = new int[n], stack = new int[n], width = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && panels[stack[top - 1]] >= panels[i]) top--;
            left[i] = top > 0 ? stack[top - 1] : -1;
            stack[top++] = i;
        }
        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && panels[stack[top - 1]] >= panels[i]) top--;
            int right = top > 0 ? stack[top - 1] : n;
            width[i] = right - left[i] - 1;
            stack[top++] = i;
        }
        return width;
    }
}

