class Solution {
public:
    vector<int> posterReach(vector<int>& panels) {
        int n = panels.size();
        vector<int> left(n), width(n), stack;
        for (int i = 0; i < n; i++) {
            while (!stack.empty() && panels[stack.back()] >= panels[i]) stack.pop_back();
            left[i] = stack.empty() ? -1 : stack.back();
            stack.push_back(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.empty() && panels[stack.back()] >= panels[i]) stack.pop_back();
            int right = stack.empty() ? n : stack.back();
            width[i] = right - left[i] - 1;
            stack.push_back(i);
        }
        return width;
    }
};

